    "en:role.object" to SkillStyleContent(nativeParallel = listOf(NativeParallelPair("Вижу дом.", "I see a house.", "В русском нет артикля вообще — «дом» без «a»/«the» звучит нормально; в английском голое существительное почти всегда требует артикль. Это первое расхождение, которое собьёт русскоговорящего чаще всего.", false, emptyList())), examples = listOf("I see a book.", "I see a dog."), why = "Английский обозначает роль слова местом в предложении, а не окончанием — поэтому дополнение выглядит точно так же, как подлежащее, просто стоит после глагола."),
    "en:verb.presentSimple" to SkillStyleContent(nativeParallel = listOf(NativeParallelPair("Он читает книгу каждый день.", "He reads a book every day.", "В русском лицо глагола различается на каждой форме (читаю/читаешь/читает/читаем/читаете/читают) — окончание меняется всегда. В английском наоборот: единственный маркер лица во всём наборе — окончание -s, и только для he/she/it; I/you/we/they вообще без окончания. Из-за этого русскоговорящие либо забывают -s там, где оно обязательно, либо по инерции добавляют его туда, где оно не нужно.", false, emptyList())), examples = listOf("The dog walks.", "She reads a book."), why = "Present Simple обозначает привычные, регулярные действия и факты; -s в 3-м лице — единственный маркер лица в этом времени."),
    "en:possessive.my" to SkillStyleContent(nativeParallel = listOf(NativeParallelPair("Моя книга.", "My book.", "Порядок владелец-перед-существительным совпадает в обоих языках, притяжательное не согласуется по числу/роду ни там, ни там на уровне «мой/my» — единственный skill из 16, где английское явление проще русского, не только польского.", true, emptyList())), examples = listOf("This is her book.", "This is their car."), why = "Английское притяжательное — закрытый список неизменяемых слов; в отличие от польского и русского, ему не нужно согласование с родом или числом существительного."),
    "en:mood.question" to SkillStyleContent(nativeParallel = listOf(NativeParallelPair("Ты видишь дом?", "Do you see a house?", "В русском вопрос — только интонация/порядок, без изменений в глаголе. В английском обязательна инверсия (аналог pl, но там это do-support, не порядок подлежащее-глагол): нужен вспомогательный do, вынесенный перед подлежащим.", false, emptyList())), examples = listOf("Do you see a house?", "Does she read?"), why = "У английского нет свободной интонационной инверсии, как в русском — вопрос всегда маркируется грамматически, через вынесенный вперёд do/does (do-support)."),
    "en:role.location" to SkillStyleContent(nativeParallel = listOf(NativeParallelPair("Я живу в доме.", "I live in a house.", "Здесь предлоги почти буквально совпадают: русское «в» и английское in оба обозначают нахождение внутри — редкий случай, когда предложная логика почти не расходится. Это исключение: другие роли (with/to/about) выбирают предлог лексически, без опоры на русский падеж (см. другие skills).", true, emptyList())), examples = listOf("I live in a house.", "I read in a car."), why = "Английские предлоги роли — отдельные, лексически закреплённые слова, а не падежные окончания; in выбирается по роли «место», а не по форме существительного."),
    "en:role.instrument" to SkillStyleContent(nativeParallel = listOf(NativeParallelPair("Я пишу ручкой.", "I write with a pen.", "Русский творительный падеж выражает роль «инструмент» одним окончанием, без предлога вообще — «ручкой» уже значит «с помощью ручки». В английском падежа нет, поэтому эта роль не может обойтись без отдельного слова with — предлог здесь не необязательное дополнение, а единственный способ показать роль.", false, emptyList())), examples = listOf("I go with my friend.", "I write with a phone."), why = "With не связан с формой существительного — как и in/to/about, это чисто лексический выбор предлога по роли, а не морфология."),
    "en:polarity.present" to SkillStyleContent(nativeParallel = listOf(NativeParallelPair("Я не вижу дом.", "I don't see a house.", "В русском отрицание — одна частица «не» перед глаголом, без вспомогательного слова. В английском нужен do/does + not, и именно do, а не глагол, несёт отрицание — русский не подсказывает, что нужно вставить лишнее слово.", false, emptyList())), examples = listOf("I do not see a car.", "I do not read."), why = "Do-support — обязательный механизм английского отрицания и вопроса: смысловой глагол сам никогда не меняется для этого, всю грамматическую нагрузку берёт вспомогательный do."),
    "en:verb.pastSimple" to SkillStyleContent(nativeParallel = listOf(NativeParallelPair("Она гуляла вчера.", "She walked yesterday.", "Русское прошедшее время согласуется с подлежащим по роду: гулял (он) / гуляла (она) / гуляли (они) — форма глагола меняется в зависимости от того, кто действует. Английское прошедшее время (walked) не различает ни род, ни число, ни лицо вообще — одна форма на всех. Здесь английская грамматика проще, но именно поэтому русскоговорящий по привычке ищет несуществующее различие.", false, emptyList())), examples = listOf("She walked to school.", "He went home."), why = "Прошедшее время в английском не зависит от лица и числа (в отличие от русского рода): walked одинаково для I/you/he/she/we/they — меняется только между настоящим и прошедшим."),
    "en:role.recipient" to SkillStyleContent(nativeParallel = listOf(NativeParallelPair("Я дал книгу своему другу.", "I gave the book to my friend.", "Русский дательный падеж («другу») сам маркирует получателя окончанием — отдельного слова не нужно. В английском нет падежных окончаний, поэтому роль «получатель» держится только на предлоге to; убрать to — потерять саму роль, а не просто изменить стиль.", false, emptyList())), examples = listOf("I give a present to my son.", "I talk to my friend."), why = "To выбирается по роли «получатель», а не по падежу; в русском дательный падеж меняет форму существительного, в английском форма не меняется вообще, меняется только предлог."),
    "en:number.plural" to SkillStyleContent(nativeParallel = listOf(NativeParallelPair("Один ребёнок, но много детей.", "One child, but many children.", "Редкое настоящее совпадение: оба языка образуют множественное число именно этого слова не регулярным окончанием, а отдельной (супплетивной) формой — ребёнок→дети, child→children, а не «childs». Здесь само исключение переносится напрямую, а не только общее правило.", true, emptyList())), examples = listOf("I see two houses.", "I see three children."), why = "Притяжательное my и прилагательное не меняются по числу — согласование с числом происходит только у самого существительного, в отличие от русского, где меняются оба слова."),
    "en:polarity.past" to SkillStyleContent(nativeParallel = listOf(NativeParallelPair("Я не видел ту машину.", "I did not see that car.", "Русское «не» — одна и та же частица в любом времени; само время несёт на себе глагол (видел — уже прошедшее). В английском отрицание в прошедшем времени, наоборот, целиком перекладывает время на вспомогательный did, а смысловой глагол (see) возвращается в базовую форму — время «переезжает» на служебное слово, а не остаётся на смысловом глаголе, как интуитивно ожидал бы русскоговорящий.", false, emptyList())), examples = listOf("I did not see him.", "She did not read the book."), why = "Did — та же механика do-support, но в прошедшем времени; смысловой глагол в отрицании прошедшего времени никогда не сохраняет -ed."),
    "en:verb.futureSimple" to SkillStyleContent(nativeParallel = listOf(NativeParallelPair("Я буду читать.", "I will read.", "Настоящее совпадение структуры: для несовершенного вида русский тоже строит будущее время аналитически — буду + инфинитив, почти как will + базовая форма в английском. Разница — в русском эта модель работает только для несовершенного вида (у совершенного будущее однословное: прочитаю), а в английском will + базовая форма — единственный способ говорить о будущем вообще, без такого разделения.", true, emptyList())), examples = listOf("I will walk home.", "She will read a book."), why = "Will — неизменяемый вспомогательный элемент будущего времени; в отличие от настоящего/прошедшего, лицо и число вообще не влияют на форму глагола."),
    "en:pronouns" to SkillStyleContent(nativeParallel = listOf(NativeParallelPair("Где моя книга? — Вот она.", "Where is my book? — Here it is.", "Выбор русского местоимения (он/она/оно) зависит от грамматического рода существительного — «книга» женского рода, поэтому «она», хотя книга явно неодушевлённый предмет. Это условность, которую нужно помнить отдельно для каждого слова. В английском для всех неодушевлённых предметов — всегда it, независимо от рода существительного в русском переводе.", false, emptyList())), examples = listOf("I see it.", "I read it."), why = "It — единственная форма для неодушевлённых предметов независимо от рода в русском переводе слова; у английских личных местоимений нет такого явного падежного различия subject/object, как у he/him, she/her — it неизменно в обеих ролях."),
    "en:verb.presentContinuous" to SkillStyleContent(nativeParallel = listOf(NativeParallelPair("Я иду домой (сейчас).", "I am going home.", "Русский вид (иду — процесс vs пойду — начало) не совпадает по границам с английским Simple/Continuous: один и тот же русский несовершенный «иду» может быть и Present Simple («I go» — привычка), и Present Continuous («I am going» — сейчас) в зависимости от контекста, который в русском не маркирован грамматически вообще.", false, emptyList())), examples = listOf("She is reading a book.", "The dog is walking."), why = "Continuous — грамматический аспект (форма be+ing), не лексический выбор глагола, как русский совершенный/несовершенный вид; один и тот же глагол walk работает и в Simple, и в Continuous."),
    "en:tense.contrast" to SkillStyleContent(nativeParallel = listOf(NativeParallelPair("Я прочитал книгу.", "I have read the book.", "Русский вид маркирует завершённость одним глаголом — «прочитал» (от читать→прочитать) сразу говорит «уже сделано, результат есть». Английский для той же идеи «результат сейчас значим» не меняет сам глагол на другой, а добавляет вспомогательный have к тому же самому read, которым только что была выражена и привычка (I read), и процесс (I am reading) — одна лексема, три разных грамматических костюма.", false, emptyList())), examples = listOf("I read a new book.", "I am reading a new book.", "I have read a new book."), why = "Три формы одного глагола показывают три разных взгляда на событие — привычку, процесс, результат — а не три разных момента времени; различие грамматическое (aspect), а не лексическое, как русский вид."),
    "en:mixed" to SkillStyleContent(nativeParallel = listOf(NativeParallelPair("Она увидела твой дом.", "She saw your house.", "В русском прошедшем времени глагол согласуется по роду с подлежащим («увидела», не «увидел» — потому что говорит она), а не с владельцем предмета («твой дом» остаётся «твой» независимо от рода того, кто увидел). В английском saw вообще не согласуется ни с кем — одна форма для всех; типичная ошибка — решить, что раз меняется владелец, должен «согласоваться» и глагол, хотя в обоих языках эти два изменения независимы.", false, emptyList())), examples = listOf("She walked her dog.", "He read their book."), why = "B1 объединяет уже отдельно выученные навыки (время, притяжательные) в одном предложении без пошаговых подсказок — тренирует именно комбинирование, а не новое правило.")
